const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,view='library',selectedBook=null,selectedUnit=null,tab='overview',busy=false,reviewMode='list',flashIndex=0,flashRevealed=false,reviewWords=[],reviewDueOnly=false,pendingReport=null,libraryBatch={running:false,stopRequested:false,summary:false,total:0,current:0,successful:[],failed:[],message:''};
const toast=t=>{const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),5200)};
const call=async fn=>{if(busy)return;busy=true;try{return await fn()}catch(e){toast(e.message||String(e))}finally{busy=false}};
const branchName=x=>({navy:'Hải quân',airforce:'Phòng không – Không quân',army:'Lục quân',unassigned:'Chưa xác định'})[x]||x;
async function refresh(){state=await window.meai.state();$('#aiBadge').textContent=state.hasKey?'Gemini đã cấu hình':'AI chưa kết nối';$('#sessionInfo').textContent=state.user?`${state.user.full_name||state.user.username} · ${state.user.role==='admin'?'Admin':'User'}`:'';$('#logoutBtn').hidden=!state.authenticated;$('#adminNav').hidden=state.user?.role!=='admin';$('#settingsNav').hidden=state.user?.role!=='admin';document.body.classList.toggle('logged-out',!state.authenticated)}
function header(title,sub,action=''){return `<div class="page-title"><div><h1>${title}</h1><div class="sub">${sub}</div></div>${action}</div>`}
async function checkSupabaseUi(){const status=$('#sbStatus');if(!status)return;status.textContent='Đang kiểm tra project và các bảng…';status.className='small';try{const r=await window.meai.checkSupabase();const failed=r.checks.filter(x=>!x.ok);status.textContent=r.ok?'Kết nối thành công. Đã tìm thấy đủ 9 bảng cần thiết.':`Kết nối được nhưng ${failed.length} bảng cần xử lý: ${failed.map(x=>x.table).join(', ')}. ${failed[0]?.error||''}`;status.className=r.ok?'connection-status good':'connection-status bad'}catch(e){status.textContent=e.message;status.className='connection-status bad'}}
function renderLogin(){view='library';$('#crumb').textContent='Đăng nhập';$('#app').innerHTML=`<div class="card settings login-card"><div class="book-icon">ME</div><h1>Đăng nhập MEAI</h1><p class="sub">Đăng nhập để truy cập giáo trình và tiến trình cá nhân. Cần cài đặt schema Supabase trước lần đầu sử dụng.</p><label class="label">Username</label><input class="input" id="loginUser" autocomplete="username"><label class="label">Mật khẩu</label><input class="input" id="loginPassword" type="password" autocomplete="current-password"><button class="btn" id="loginBtn" style="margin-top:16px;width:100%">Đăng nhập</button><details class="config-box" ${state.supabaseConfigured?'':'open'}><summary>Cấu hình Supabase</summary><p class="small">Nhập Project URL và khóa secret/service_role. Khóa được lưu mã hóa trong hồ sơ Windows của bạn.</p><label class="label">Project URL</label><input class="input" id="sbUrl" value="${esc(state.supabaseUrl||'')}" placeholder="https://<project-ref>.supabase.co"><label class="label">Secret/service_role key</label><input class="input" id="sbKey" type="password" placeholder="${state.supabaseConfigured?'Đã lưu; để trống nếu không đổi':'Dán khóa Supabase'}"><div class="foot-actions"><button class="btn secondary" id="saveSb">Lưu kết nối</button><button class="btn secondary" id="checkSb">Kiểm tra Supabase</button></div><div id="sbStatus" class="small" role="status"></div></details><p class="small">Tài khoản đầu tiên sau khi chạy schema: <b>admin1 / admin123</b>.</p></div>`;
$('#saveSb').onclick=()=>call(async()=>{await window.meai.saveSupabaseConfig({url:$('#sbUrl').value,key:$('#sbKey').value});await refresh();renderLogin();await checkSupabaseUi();toast('Đã lưu cấu hình Supabase; kết quả kiểm tra hiển thị bên dưới.')});$('#checkSb').onclick=()=>call(checkSupabaseUi);
$('#loginBtn').onclick=()=>call(async()=>{const login=await window.meai.login({username:$('#loginUser').value,password:$('#loginPassword').value});await refresh();view='library';render();toast('Đăng nhập thành công.');if(login.reminders?.length){alert('Lời nhắc từ Admin:\n\n'+login.reminders.map(x=>'• '+x.message).join('\n'));await window.meai.ackReminders(login.reminders.map(x=>x.id))}});
$('#loginPassword').onkeydown=e=>{if(e.key==='Enter')$('#loginBtn').click()}}
function renderPasswordChange(){view='password';$('#crumb').textContent='Đổi mật khẩu bắt buộc';document.querySelectorAll('.nav').forEach(b=>b.classList.remove('active'));$('#app').innerHTML=header('Đổi mật khẩu bắt buộc','Tài khoản mới cần thay mật khẩu tạm trước khi tiếp tục học.')+'<div class="card settings" style="max-width:620px;margin:40px auto"><p class="sub">Chọn mật khẩu cá nhân dài ít nhất 10 ký tự. Mật khẩu mới sẽ được lưu vào Supabase dưới dạng hash.</p><label class="label" for="firstPassword">Mật khẩu mới</label><input class="input" id="firstPassword" type="password" autocomplete="new-password"><label class="label" for="confirmFirstPassword">Nhập lại mật khẩu mới</label><input class="input" id="confirmFirstPassword" type="password" autocomplete="new-password"><button class="btn" id="saveFirstPassword" style="margin-top:16px">Lưu mật khẩu mới</button></div>';$('#saveFirstPassword').onclick=()=>call(async()=>{const password=$('#firstPassword').value,confirm=$('#confirmFirstPassword').value;if(password!==confirm)throw Error('Hai mật khẩu chưa trùng nhau.');await window.meai.changePassword({newPassword:password});await refresh();view='library';render();toast('Đã đổi mật khẩu. Bạn có thể bắt đầu học.')})}
function render(){if(!state?.authenticated){renderLogin();return}if(state.user?.must_change_password){renderPasswordChange();return}if(view==='settings'&&state.user?.role!=='admin')view='library';document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent=view==='library'?'Thư viện giáo trình':view==='settings'?'Cài đặt AI':view==='review'?'Ôn từ vựng':view==='progress'?'Tiến trình của tôi':view==='admin'?'Quản trị dữ liệu':selectedBook?.title||'Học liệu';if(view==='admin'){if(state.user.role==='admin')renderAdmin();else{view='library';renderLibrary()}return}if(view==='progress'){renderProgress();return}if(view==='library'){renderLibrary();if(state.user.role!=='admin')document.querySelectorAll('#importBtn,#importEmpty,#importTextBtn,#importUrlBtn').forEach(x=>x.remove());return}view==='settings'?renderSettings():view==='review'?renderReview():renderBook()}
async function renderAdmin(){try{const d=await window.meai.adminData();const users=d.users||[],history=d.history||[],progress=d.progress||[],overall=d.overallScore===null?'—':Number(d.overallScore).toFixed(1);$('#app').innerHTML=header('Quản trị tài khoản và dữ liệu','Theo dõi kết quả từng người học, xem lịch sử gần đây và quản lý tài khoản/giáo trình.')+`<div class="stat-row"><span class="stat">${users.length} tài khoản</span><span class="stat">${d.books.length} giáo trình</span><span class="stat">${d.unitCount} Unit</span><span class="stat">${d.totalActivities} lượt học</span><span class="stat">Điểm bài tập TB ${overall}/10</span><span class="stat">AI: ${d.aiUsage?.calls||0} lượt · ${((d.aiUsage?.inputTokens||0)+(d.aiUsage?.outputTokens||0)).toLocaleString()} token</span></div><div class="admin-grid"><div class="card"><h3 class="section-title">Tạo tài khoản</h3><label class="label">Username</label><input class="input" id="newUsername"><label class="label">Họ tên</label><input class="input" id="newFullName"><label class="label">Mật khẩu (ít nhất 6 ký tự)</label><input class="input" type="password" id="newPassword"><label class="label">Quyền</label><select class="select" id="newRole"><option value="user">User</option><option value="admin">Admin</option></select><div class="foot-actions"><button class="btn" id="createUserBtn">Tạo tài khoản</button><button class="btn secondary" id="importUsersBtn">Nhập Excel</button></div><p class="small">Excel .xlsx, trang tính đầu tiên; tiêu đề cột: username, password, full_name, role. username và password là bắt buộc; role để trống sẽ là user. Mọi tài khoản mới cần đổi mật khẩu ở lần đăng nhập đầu tiên.</p></div><div class="card"><h3 class="section-title">Tài khoản</h3><div class="table-wrap"><table><thead><tr><th>Nhắc</th><th>Username</th><th>Họ tên</th><th>Role</th><th>Đổi mật khẩu</th><th>Tạo lúc</th></tr></thead><tbody>${users.map(u=>`<tr><td><input type="checkbox" data-remind-user="${esc(u.id)}"></td><td>${esc(u.username)}</td><td>${esc(u.full_name||'')}</td><td>${esc(u.role)}</td><td>${u.must_change_password?'Bắt buộc':'Đã đổi'}</td><td>${esc((u.created_at||'').slice(0,10))}</td></tr>`).join('')}</tbody></table></div><label class="label">Lời nhắc</label><input class="input" id="reminderMessage" placeholder="Hãy tiếp tục học Unit hôm nay"><button class="btn secondary" id="sendReminderBtn" style="margin-top:10px">Gửi cho user đã chọn</button></div></div><div class="card" style="margin-top:16px"><h3 class="section-title">Tiến trình và kết quả theo tài khoản</h3><div class="table-wrap"><table><thead><tr><th>Người học</th><th>Lượt học</th><th>Lượt AI</th><th>Token</th><th>Unit đã học</th><th>Độ phủ học liệu</th><th>Lần học gần nhất</th><th>Lượt làm bài</th><th>Điểm TB / 10</th><th>Phiên hội thoại được chấm</th><th>Điểm hội thoại TB / 10</th></tr></thead><tbody>${progress.map(p=>`<tr><td>${esc(p.full_name||p.username)}<div class="small">${esc(p.username)}</div></td><td>${p.activities}</td><td>${p.aiCalls}</td><td>${(p.inputTokens+p.outputTokens).toLocaleString()}</td><td>${p.unitsVisited}/${d.unitCount}</td><td><div class="progress-wrap"><span style="width:${p.coveragePercent}%"></span></div><div class="small">${p.coveragePercent}%</div></td><td>${p.lastActive?esc(p.lastActive.slice(0,10)):'Chưa có'}</td><td>${p.exerciseCount}</td><td>${p.averageScore===null?'—':esc(p.averageScore)}</td><td>${p.scoredConversations||0}</td><td>${p.averageConversationScore===null?'—':esc(p.averageConversationScore)}</td></tr>`).join('')}</tbody></table></div><p class="small">Độ phủ tính theo số Unit có hoạt động đã ghi nhận trên tổng Unit trong thư viện; điểm bài tập và điểm hội thoại được tổng hợp riêng.</p></div><div class="card" style="margin-top:16px"><div class="row" style="justify-content:space-between"><h3 class="section-title">Lịch sử học gần đây</h3><select class="select" id="historyUserFilter" style="max-width:260px"><option value="all">Tất cả tài khoản</option>${users.map(u=>`<option value="${esc(u.id)}">${esc(u.full_name||u.username)}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Unit</th><th>Hoạt động</th><th>Điểm / 10</th><th>Ngày</th><th>Bài làm / phản hồi</th></tr></thead><tbody>${history.map(h=>`<tr data-history-user="${esc(h.user_id)}"><td>${esc(h.users?.username||'')}</td><td>${esc(h.units?.unit_name||'')}</td><td>${esc(h.activity_type||'')}</td><td>${esc(h.score??'—')}</td><td>${esc((h.created_at||'').slice(0,10))}</td><td>${esc((h.progress_comparison||h.ai_feedback||h.user_submission||'').slice(0,180))}</td></tr>`).join('')}</tbody></table></div><p class="small">Hiển thị tối đa 500 hoạt động mới nhất. Bảng thống kê phía trên tính trên toàn bộ lịch sử đã ghi.</p></div><div class="card" style="margin-top:16px"><h3 class="section-title">Giáo trình trên Supabase</h3><div class="table-wrap"><table><thead><tr><th>Tên giáo trình</th><th>Tệp</th><th>Chuyên ngành</th><th>Tạo lúc</th></tr></thead><tbody>${d.books.map(b=>`<tr><td>${esc(b.book_name)}</td><td>${esc(b.filename||'')}</td><td>${esc(branchName(b.branch))}</td><td>${esc((b.created_at||'').slice(0,10))}</td></tr>`).join('')}</tbody></table></div></div>${auditListMarkup(d.auditLogs||[],d.auditLogsError||'')}${reportListMarkup(d.reports||[],d.reportsError||'')}`;
$('#createUserBtn').onclick=()=>call(async()=>{const created=await window.meai.createUser({username:$('#newUsername').value,full_name:$('#newFullName').value,password:$('#newPassword').value,role:$('#newRole').value});await refresh();await renderAdmin();toast(`Supabase đã lưu tài khoản ${created.username}.`)});
$('#importUsersBtn').onclick=()=>call(async()=>{const r=await window.meai.importUsersExcel();if(!r)return;const details=r.errors.length?` Bỏ qua ${r.errors.length} dòng. ${r.errors.slice(0,3).join(' ')}`:'';toast(`Đã thêm ${r.created}/${r.selected} tài khoản.${details}`);renderAdmin()});
$('#sendReminderBtn').onclick=()=>call(async()=>{const userIds=[...document.querySelectorAll('[data-remind-user]:checked')].map(x=>x.dataset.remindUser);await window.meai.sendReminders({userIds,message:$('#reminderMessage').value});toast(`Đã gửi ${userIds.length} lời nhắc.`);renderAdmin()});
$('#historyUserFilter').onchange=e=>document.querySelectorAll('[data-history-user]').forEach(row=>row.hidden=e.target.value!=='all'&&row.dataset.historyUser!==e.target.value);document.querySelectorAll('[data-resolve-report]').forEach(btn=>btn.onclick=()=>call(async()=>{await window.meai.resolveContentReport({reportId:btn.dataset.resolveReport,resolved:btn.dataset.resolved==='true'});await renderAdmin();toast('Đã cập nhật trạng thái báo lỗi.')}))}catch(e){toast(e.message)}}
function progressAdvice(rows){const m=new Map();for(const h of rows)if(h.activity_type==='exercise'&&h.score!==null&&h.unit_id){const x=m.get(h.unit_id)||{name:h.units?.unit_name||'Unit',sum:0,count:0};x.sum+=Number(h.score)||0;x.count++;m.set(h.unit_id,x)}const weak=[...m.entries()].map(([id,x])=>({id,...x,avg:x.sum/x.count})).sort((a,b)=>a.avg-b.avg).slice(0,3);return weak.length?`<div class="card" style="margin-bottom:16px"><h3 class="section-title">Gợi ý học tiếp</h3><p class="small">Ưu tiên ôn Unit có điểm luyện tập thấp; kết quả mới sẽ tự điều chỉnh gợi ý này.</p>${weak.map(x=>`<div class="row"><span>${esc(x.name)}</span><span class="tag">Trung bình ${x.avg.toFixed(1)}/10</span></div>`).join('')}</div>`:'<div class="notice" style="margin-bottom:16px">Làm một bài luyện tập để MEAI gợi ý nội dung nên ôn tiếp.</div>'}
async function renderProgress(){try{const result=await window.meai.myProgress(),rows=result.history||[],units=new Set(rows.map(x=>x.unit_id).filter(Boolean)),scores=rows.filter(x=>(x.activity_type==='exercise'||x.activity_type==='conversation')&&x.score!==null&&x.score!==undefined).map(x=>Number(x.score)),average=scores.length?(scores.reduce((a,b)=>a+b,0)/scores.length).toFixed(1):'—',latestWriting=rows.find(x=>x.activity_type==='writing'&&x.progress_comparison),bars=rows.filter(x=>(x.activity_type==='exercise'||x.activity_type==='conversation')&&x.score!==null&&x.score!==undefined).slice(0,12).reverse();$('#app').innerHTML=header('Tiến trình của tôi','Lịch sử, điểm số và nhận xét chỉ hiển thị tài khoản đang đăng nhập.')+`<div class="stat-row"><span class="stat">${rows.length} lượt học</span><span class="stat">${units.size}/${result.unitCount} Unit có hoạt động</span><span class="stat">${scores.length} lượt đã chấm</span><span class="stat">Điểm trung bình các lượt đã chấm ${average}/10</span><span class="stat">AI hôm nay: ${result.aiUsage?.calls||0}/${result.aiUsage?.dailyQuota||60} · ${(Number(result.aiUsage?.inputTokens||0)+Number(result.aiUsage?.outputTokens||0)).toLocaleString()} token</span></div>${progressAdvice(rows)}${latestWriting?`<div class="card" style="margin-bottom:16px"><h3 class="section-title">Nhận xét tiến bộ bài viết gần nhất</h3><div class="summary">${esc(latestWriting.progress_comparison)}</div></div>`:''}${bars.length?`<div class="card" style="margin-bottom:16px"><h3 class="section-title">Điểm luyện tập gần đây</h3><div class="score-chart">${bars.map(x=>`<div class="score-column" title="${esc(x.activity_type==='conversation'?'Hội thoại':'Bài tập')} · ${esc(x.score)}/10 · ${esc((x.created_at||'').slice(0,10))}"><span>${esc(x.score)}</span><div style="height:${Math.max(4,Math.min(10,Number(x.score)||0))*14}px"></div><small>${esc((x.created_at||'').slice(5,10))}</small></div>`).join('')}</div></div>`:''}<div class="card"><h3 class="section-title">Lịch sử học của tôi</h3><div class="table-wrap"><table><thead><tr><th>Unit</th><th>Hoạt động</th><th>Điểm / 10</th><th>Ngày</th><th>Bài làm / nhận xét</th></tr></thead><tbody>${rows.map(h=>`<tr><td>${esc(h.units?.unit_name||'')}</td><td>${esc(h.activity_type||'')}</td><td>${esc(h.score??'—')}</td><td>${esc((h.created_at||'').slice(0,10))}</td><td>${esc((h.progress_comparison||h.ai_feedback||h.user_submission||'').slice(0,240))}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty-inline">Chưa có hoạt động học được ghi nhận. Hãy làm bài luyện tập, gửi bài viết hoặc luyện hội thoại theo Unit.</div>'}</div>`}catch(e){toast(e.message)}}
function batchPanelMarkup(){if(!libraryBatch.running&&!libraryBatch.summary)return '';const finished=libraryBatch.successful.length+libraryBatch.failed.length,pct=libraryBatch.total?Math.round(finished/libraryBatch.total*100):0,title=libraryBatch.running?(libraryBatch.stopRequested?'Đang dừng sau Unit hiện tại…':libraryBatch.message):libraryBatch.message;return `<section class="card batch-analysis-card" role="status"><div class="batch-analysis-head"><div><strong>${esc(title)}</strong><div class="small">${finished}/${libraryBatch.total} Unit đã xử lý · ${libraryBatch.successful.length} thành công · ${libraryBatch.failed.length} lỗi</div></div>${libraryBatch.running?'<button class="btn danger" id="stopBatchAnalysis">Dừng</button>':''}</div><div class="progress-wrap"><span style="width:${pct}%"></span></div>${!libraryBatch.running&&libraryBatch.summary&&libraryBatch.failed.length?`<div class="batch-failures"><strong>Unit lỗi:</strong><ul>${libraryBatch.failed.map(x=>`<li>${esc(x.name)}${x.error?` — ${esc(x.error)}`:''}</li>`).join('')}</ul></div>`:''}</section>`}
function updateBatchPanel(){const panel=$('#batchAnalysisPanel');if(!panel)return;panel.innerHTML=batchPanelMarkup();$('#stopBatchAnalysis')?.addEventListener('click',()=>{libraryBatch.stopRequested=true;libraryBatch.message='Đang dừng sau Unit hiện tại…';updateBatchPanel()})}
async function waitBetweenBatchUnits(){const end=Date.now()+2500;while(!libraryBatch.stopRequested&&Date.now()<end)await new Promise(resolve=>setTimeout(resolve,100))}
async function analyzeAllUnanalyzedUnits(){if(libraryBatch.running||state.user?.role!=='admin')return;const queue=[];for(const book of state.books||[])for(const unit of book.units||[])if(!unit.analysis)queue.push({bookId:book.id,bookTitle:book.title,unitId:unit.id,unitTitle:unit.title});if(!queue.length){toast('Tất cả Unit đã được phân tích.');return}libraryBatch={running:true,stopRequested:false,summary:false,total:queue.length,current:0,successful:[],failed:[],message:''};renderLibrary();for(let i=0;i<queue.length;i++){if(libraryBatch.stopRequested)break;const item=queue[i];libraryBatch.current=i+1;libraryBatch.message=`Đang phân tích ${i+1}/${queue.length}: ${item.unitTitle}`;updateBatchPanel();try{const result=await window.meai.analyzeUnit(item.bookId,item.unitId);if(!result||typeof result!=='object')throw Error('Hàm phân tích không trả về kết quả.');libraryBatch.successful.push(item.unitTitle)}catch(e){libraryBatch.failed.push({name:item.bookTitle?`${item.bookTitle} — ${item.unitTitle}`:item.unitTitle,error:String(e?.message||e||'Lỗi không xác định')})}try{await refresh()}catch{}if(view==='library')renderLibrary();if(libraryBatch.stopRequested)break;if(i<queue.length-1){libraryBatch.message=`Đã xử lý ${i+1}/${queue.length}. Nghỉ 2,5 giây trước Unit tiếp theo.`;updateBatchPanel();await waitBetweenBatchUnits()}}const wasStopped=libraryBatch.stopRequested,done=libraryBatch.successful.length+libraryBatch.failed.length;libraryBatch.running=false;libraryBatch.summary=true;libraryBatch.message=wasStopped?`Đã dừng theo yêu cầu sau ${done}/${libraryBatch.total} Unit.`:`Hoàn tất phân tích ${done}/${libraryBatch.total} Unit.`;await refresh().catch(()=>{});if(view==='library')renderLibrary();else updateBatchPanel();toast(`${libraryBatch.message} ${libraryBatch.successful.length} thành công, ${libraryBatch.failed.length} lỗi.`)}
function renderLibrary(){const books=state.books||[],admin=state.user?.role==='admin',pending=books.reduce((n,b)=>n+(b.units||[]).filter(u=>!u.analysis).length,0),actions=admin?`<div class="row"><button class="btn" id="importBtn">＋ Nhập giáo trình</button><button class="btn secondary" id="importTextBtn">Nhập văn bản</button><button class="btn secondary" id="importUrlBtn">Nhập đường dẫn</button><button class="btn" id="batchAnalyzeBtn" ${pending===0||libraryBatch.running?'disabled':''}>Phân tích tất cả Unit chưa phân tích</button></div>`:'';$('#app').innerHTML=header('Thư viện giáo trình','Nhập giáo trình để MEAI tự nhận diện Unit và phân tích từ vựng, bài đọc, bài tập ngay sau khi nhập.',actions)+(admin?`<div id="batchAnalysisPanel">${batchPanelMarkup()}</div>`:'')+(books.length?`<div class="grid">${books.map(b=>`<article class="card book"><div class="book-top"><div class="book-icon">ME</div><span class="tag">${esc(branchName(b.branch))}</span></div><div><h3>${esc(b.title)}</h3><div class="muted">${esc(b.filename)} · ${b.units.length} phần</div></div><div class="stat-row"><span class="stat">${b.units.filter(u=>u.analysis).length}/${b.units.length} Unit đã phân tích</span><span class="stat">${b.units.reduce((n,u)=>n+(u.analysis?.vocabulary?.length||0),0)} từ vựng</span></div><div class="book-foot"><button class="btn" data-open="${b.id}">Mở giáo trình</button><button class="btn secondary" data-export="${b.id}">Xuất dữ liệu</button></div></article>`).join('')}</div>`:`<div class="card empty"><div class="book-icon" style="margin:auto">ME</div><h2>Bắt đầu với giáo trình đầu tiên</h2><p>MEAI sẽ trích xuất văn bản, tách nội dung theo Unit hoặc phần, rồi dùng Gemini 3.8 Flash phân loại học liệu. Kết quả được lưu trên Supabase dùng chung và có dẫn chứng để đối chiếu.</p><button class="btn" id="importEmpty">Chọn giáo trình</button><p class="small" style="margin-top:14px">Hỗ trợ PDF có chữ, DOCX, PPTX, TXT, MD và liên kết HTTPS đến bài viết. PDF scan hoặc slide chỉ có ảnh cần OCR trước khi nhập.</p></div>`);
$('#importBtn')?.addEventListener('click',importBook);$('#importEmpty')?.addEventListener('click',importBook);$('#importTextBtn')?.addEventListener('click',()=>$('#textImportDialog').showModal());$('#importUrlBtn')?.addEventListener('click',importUrl);document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selectedBook=state.books.find(x=>x.id===b.dataset.open);selectedUnit=selectedBook?.units[0]?.id;view='book';tab='overview';render()});document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>call(async()=>{await window.meai.exportBook(b.dataset.export);toast('Đã xuất dữ liệu giáo trình.')}));$('#batchAnalyzeBtn')?.addEventListener('click',analyzeAllUnanalyzedUnits)}
async function importText(){if(busy)return;const title=$('#textImportTitle').value.trim(),text=$('#textImportBody').value.trim();if(text.length<250){toast('Nhập ít nhất 250 ký tự.');return}let imported=null;await call(async()=>{imported=await window.meai.importText({title,text});if(!imported)return;$('#textImportDialog').close();$('#textImportBody').value='';await refresh();selectedBook=state.books.find(b=>b.id===imported.id);selectedUnit=selectedBook?.units[0]?.id;view='book';render();toast(`Đã nhập văn bản, nhận diện ${imported.unitCount} phần.`)});if(imported?.hasKey)await analyzeBook(imported.id)}
async function importUrl(){const url=prompt('Dán địa chỉ HTTPS của bài viết:');if(!url)return;let imported=null;await call(async()=>{imported=await window.meai.importUrl({url});await refresh();selectedBook=state.books.find(b=>b.id===imported.id);selectedUnit=selectedBook?.units[0]?.id;view='book';render();toast(`Đã nhập bài viết, nhận diện ${imported.unitCount} phần.`)});if(imported?.hasKey)await analyzeBook(imported.id)}
async function importBook(){if(busy)return;busy=true;toast('Đang đọc giáo trình…');let imported=null;try{imported=await window.meai.importBook();if(!imported)return;await refresh();selectedBook=state.books.find(b=>b.id===imported.id);selectedUnit=selectedBook.units[0]?.id;view='book';render();toast(`Đã nhập tài liệu, nhận diện ${imported.unitCount} phần.`)}catch(e){toast(e.message)}finally{busy=false;await refresh();render()}if(imported){if(imported.hasKey)await analyzeBook(imported.id);else toast('Đã nhập tài liệu. Hãy cấu hình Gemini API key để bắt đầu phân tích tự động.')}}
async function analyzeBook(id){if(busy)return;busy=true;toast('Đang phân tích các Unit. Có thể mất vài phút tùy dung lượng tài liệu.');try{const r=await window.meai.analyzeBook(id);await refresh();selectedBook=state.books.find(b=>b.id===id);render();toast(`Đã phân tích ${r.done} phần. ${r.failed.length?`Có ${r.failed.length} phần cần thử lại.`:'Hoàn tất.'}`);if(r.failed.length)console.log(r.failed)}catch(e){toast(e.message)}finally{busy=false}}
function renderBook(){selectedBook=state.books.find(b=>b.id===selectedBook?.id)||state.books[0];if(!selectedBook){view='library';renderLibrary();return}const b=selectedBook,u=b.units.find(x=>x.id===selectedUnit)||b.units[0];selectedUnit=u?.id;const left=`<div class="card"><div class="book-top"><div><h3>${esc(b.title)}</h3><div class="muted">${esc(branchName(b.branch))}</div></div><span class="tag">${b.units.length} phần</span></div><div class="unit-list">${b.units.map(x=>`<button class="unit-btn ${x.id===u?.id?'active':''}" data-unit="${x.id}">${esc(x.title)}<span class="review-pill ${x.reviewStatus==='approved'?'review-approved':'review-pending'}">${x.reviewStatus==='approved'?'Đã duyệt':'Chưa duyệt'}</span><small>${x.analysis?`${x.analysis.vocabulary.length} từ · ${x.analysis.exercises.length} bài tập`:'Chưa phân tích'}</small></button>`).join('')}</div><hr class="divider"><button class="btn" id="analyzeAll" style="width:100%">Phân tích phần còn lại</button><button class="btn secondary" id="deleteBook" style="width:100%;margin-top:8px">Xóa giáo trình</button></div>`;
const tabs=[['overview','Tổng quan'],['vocabulary','Từ vựng'],['readings','Bài đọc'],['exercises','Bài tập gốc'],['grammar','Lý thuyết'],['practice','Luyện tập AI'],['extensions','Học liệu mở rộng'],['writing','Luyện viết'],['conversation','Hội thoại'],['ask','Hỏi AI']];
const right=u?`<div class="card"><div class="unit-heading"><div><h2>${esc(u.title)}</h2><div class="muted">Trang nguồn: ${u.pages?.length?u.pages.join(', '):'chưa xác định'} · ${u.analysis?'Đã phân tích':'Chưa phân tích'}</div><div class="unit-review-meta"><span class="review-pill ${u.reviewStatus==='approved'?'review-approved':'review-pending'}">${u.reviewStatus==='approved'?'Đã duyệt':'Chưa duyệt'}</span>${u.reviewStatus==='approved'?`<span class="small">${esc(u.reviewedByName||'Admin')}${u.reviewedAt?` · ${esc(new Date(u.reviewedAt).toLocaleString('vi-VN'))}`:''}</span>`:''}</div></div><div class="unit-actions">${state.user.role==='admin'?`<button class="btn secondary" id="approveUnit">${u.reviewStatus==='approved'?'Bỏ duyệt':'Đánh dấu đã duyệt'}</button>`:''}<button class="btn secondary" id="reanalyze">${u.analysis?'Phân tích lại':'Phân tích Unit'}</button></div></div><div class="tabs">${tabs.map(([id,label])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}">${label}${id==='vocabulary'&&u.analysis?` (${u.analysis.vocabulary.length})`:id==='exercises'&&u.analysis?` (${u.analysis.exercises.length})`:''}</button>`).join('')}</div>${renderTab(b,u)}</div>`:'';
$('#app').innerHTML=`<div class="page-title"><div><h1>${esc(b.title)}</h1><div class="sub">Nội dung được phân tích riêng theo từng Unit. Chọn mục bên dưới để xem học liệu và hỏi AI về từ vựng trong ngữ cảnh.</div></div><button class="btn secondary" id="back">← Thư viện</button></div><div class="workspace">${left}${right}</div>`;
$('#back').onclick=()=>{view='library';refresh().then(render)};$('#approveUnit')?.addEventListener('click',()=>call(async()=>{const approved=u.reviewStatus!=='approved';await window.meai.setUnitApproval({bookId:b.id,unitId:u.id,approved});await refresh();selectedBook=state.books.find(x=>x.id===b.id);toast(approved?'Đã đánh dấu Unit đã duyệt.':'Đã bỏ duyệt Unit.');renderBook()}));document.querySelectorAll('[data-save-vocabulary]').forEach(btn=>btn.onclick=()=>call(async()=>{const index=Number(btn.dataset.saveVocabulary),editor=btn.closest('[data-vocab-editor]'),value=Object.fromEntries([...editor.querySelectorAll('[data-vocab-field]')].map(el=>[el.dataset.vocabField,el.value]));await window.meai.updateVocabulary({bookId:b.id,unitId:u.id,index,value});await refresh();selectedBook=state.books.find(x=>x.id===b.id);renderBook();toast('Đã lưu từ vựng và cập nhật đối chiếu nguồn.')}));const reportGroups={vocabulary:u.analysis?.vocabulary||[],exercise:u.analysis?.exercises||[],reading:u.analysis?.readings||[],grammar:u.analysis?.grammar||[],ai_practice:u.practice?.questions||[],extension_vocabulary:u.extensions?.vocabulary||[],extension_exercise:u.extensions?.exercises||[],extension_reading:u.extensions?.readings||[]};document.querySelectorAll('[data-report]').forEach(btn=>btn.onclick=()=>{const type=btn.dataset.report,reportedContent=reportGroups[type]?.[Number(btn.dataset.reportIndex)];if(!reportedContent)return;pendingReport={bookId:b.id,unitId:u.id,contentType:type,reportedContent};$('#reportContentPreview').value=JSON.stringify(reportedContent,null,2);$('#reportNote').value='';$('#reportDialog').showModal()});document.querySelectorAll('[data-unit]').forEach(x=>x.onclick=()=>{selectedUnit=x.dataset.unit;tab='overview';renderBook()});document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;renderBook()});$('#analyzeAll').onclick=()=>analyzeBook(b.id);$('#reanalyze').onclick=()=>call(async()=>{await window.meai.analyzeUnit(b.id,u.id);await refresh();selectedBook=state.books.find(x=>x.id===b.id);toast('Đã phân tích lại Unit.');renderBook()});$('#deleteBook').onclick=async()=>{if(confirm('Xóa giáo trình và toàn bộ học liệu đã phân tích của giáo trình này?')){await call(async()=>{await window.meai.deleteBook(b.id);await refresh();view='library';render();toast('Đã xóa giáo trình.')})}};$('#askSend')?.addEventListener('click',ask);$('#analyzeNow')?.addEventListener('click',()=>call(async()=>{await window.meai.analyzeUnit(b.id,u.id);await refresh();selectedBook=state.books.find(x=>x.id===b.id);renderBook()}));$('#makePractice')?.addEventListener('click',()=>call(async()=>{const practice=await window.meai.generatePractice({bookId:b.id,unitId:u.id,count:8});await refresh();selectedBook=state.books.find(x=>x.id===b.id);tab='practice';renderBook();toast(`Đã tạo ${practice.questions.length} câu hỏi luyện tập bổ sung.`)}));$('#newPractice')?.addEventListener('click',()=>call(async()=>{const practice=await window.meai.generatePractice({bookId:b.id,unitId:u.id,count:8});await refresh();selectedBook=state.books.find(x=>x.id===b.id);renderBook();toast(`Đã tạo ${practice.questions.length} câu hỏi mới.`)}));$('#generateExtensions')?.addEventListener('click',()=>call(async()=>{await window.meai.generateExtensions({bookId:b.id,unitId:u.id});await refresh();selectedBook=state.books.find(x=>x.id===b.id);toast('Đã lưu học liệu mở rộng từ Cerebras lên Supabase.');renderBook()}));$('#submitPractice')?.addEventListener('click',()=>gradePractice(u));$('#checkWriting')?.addEventListener('click',()=>call(async()=>{const answer=await window.meai.checkWriting({bookId:b.id,unitId:u.id,text:$('#writingInput').value});$('#writingAnswer').innerHTML=`<div class="answer"><b>Điểm: ${esc(answer.score)}/10</b><h4>Bản sửa</h4><div>${esc(answer.corrected)}</div><h4>Điểm tốt</h4><div>${(answer.strengths||[]).map(esc).join('<br>')}</div><h4>Lỗi cần sửa</h4>${(answer.corrections||[]).map(x=>`<div>${esc(x.original)} → <b>${esc(x.corrected)}</b> · ${esc(x.reason)}</div>`).join('')}<h4>So sánh tiến bộ</h4><div>${esc(answer.progressComparison)}</div><h4>Nên luyện tiếp</h4><div>${(answer.recommendations||[]).map(esc).join('<br>')}</div></div>`}));$('#chatStart')?.addEventListener('click',()=>call(async()=>{await window.meai.chatStart({bookId:b.id,unitId:u.id,scenarioId:$('#chatScenario').value});await refresh();selectedBook=state.books.find(x=>x.id===b.id);tab='conversation';renderBook()}));$('#chatSend')?.addEventListener('click',()=>call(async()=>{const session=[...(state.sessions||[])].reverse().find(s=>s.bookId===b.id&&s.unitId===u.id);if(!session)throw Error('Bắt đầu hội thoại trước.');await window.meai.chatReply({sessionId:session.id,text:$('#chatInput').value});await refresh();selectedBook=state.books.find(x=>x.id===b.id);tab='conversation';renderBook()}));$('#endChat')?.addEventListener('click',()=>call(async()=>{const session=[...(state.sessions||[])].reverse().find(s=>s.bookId===b.id&&s.unitId===u.id);if(!session)throw Error('Không tìm thấy phiên hội thoại.');const feedback=await window.meai.chatFeedback({sessionId:session.id});await refresh();selectedBook=state.books.find(x=>x.id===b.id);renderBook();toast(`Đã lưu nhận xét hội thoại. Điểm tổng hợp: ${feedback.overallScore}/10.`)}));if(state.user.role!=='admin')document.querySelectorAll('#analyzeAll,#reanalyze,#deleteBook,#analyzeNow,#approveUnit').forEach(x=>x.remove());document.querySelectorAll('[data-ask-term]').forEach(x=>x.onclick=()=>{tab='ask';renderBook();$('#termInput').value=x.dataset.askTerm;$('#questionInput').focus()});document.querySelectorAll('[data-speak]').forEach(x=>x.onclick=()=>speakEnglish(x.dataset.speak))}
function speakEnglish(text){if(!window.speechSynthesis){toast('Phát âm chưa được hỗ trợ trên thiết bị này.');return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.88;window.speechSynthesis.speak(u)}
function vocabEditorMarkup(v,i){if(state.user?.role!=='admin')return '';const field=(key,label,multiline=false)=>`<label class="label">${label}</label>${multiline?`<textarea class="textarea" data-vocab-field="${key}">${esc(v[key]||'')}</textarea>`:`<input class="input" data-vocab-field="${key}" value="${esc(v[key]||'')}">`}`;return `<details class="vocab-editor" data-vocab-editor="${i}"><summary>Sửa nội dung từ vựng</summary>${field('term','Từ / thuật ngữ')}${field('meaning','Nghĩa')}${field('partOfSpeech','Từ loại')}${field('ipa','Phiên âm IPA')}${field('example','Ví dụ trong nguồn',true)}${field('evidence','Dẫn chứng',true)}<button class="btn secondary" data-save-vocabulary="${i}">Lưu từ vựng</button></details>`}
function renderPracticeItem(q,i){const labels={multiple_choice:'Trắc nghiệm',fill_blank:'Điền từ',sentence_order:'Sắp xếp câu',reading_comprehension:'Đọc hiểu'},type=q.type||'multiple_choice';return `<div class="data-item"><b>Câu ${i+1} · ${esc(labels[type]||labels.multiple_choice)}. ${esc(q.question)}</b>${type==='fill_blank'||type==='sentence_order'?`<input class="input" id="practice-answer-${i}" style="margin-top:10px" placeholder="Nhập câu trả lời">`:`<div style="margin-top:10px">${(q.options||[]).map((o,j)=>`<label style="display:block;margin:8px 0"><input type="radio" name="practice-${i}" value="${j}"> ${esc(o)}</label>`).join('')}</div>`}<div class="evidence">Căn cứ trong giáo trình: ${esc(q.evidence)}</div><button class="btn secondary" data-report="ai_practice" data-report-index="${i}">Báo lỗi nội dung</button><div class="small" id="practiceExp-${i}" hidden></div></div>`}
function gradePractice(u){let score=0;const questions=u.practice.questions;for(let i=0;i<questions.length;i++){const q=questions[i],free=q.type==='fill_blank'||q.type==='sentence_order';let ok=false;if(free){const norm=x=>String(x||'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();ok=norm($('#practice-answer-'+i).value)===norm(q.answerText)}else{const selected=document.querySelector(`input[name="practice-${i}"]:checked`);ok=!!selected&&Number(selected.value)===q.answerIndex}if(ok)score++;const el=$('#practiceExp-'+i);el.hidden=false;const expected=free?q.answerText:(q.options||[])[q.answerIndex]||q.answerText;el.innerHTML=`<b>${ok?'Đúng':'Đáp án mẫu: '+esc(expected)}.</b> ${esc(q.explanation)}`}const rate=score/questions.length,advice=rate<.6?'Gợi ý: xem lại từ vựng và bài đọc của Unit rồi làm lại.':rate<.85?'Gợi ý: ôn các câu sai rồi thử thêm một bộ câu hỏi.':'Bạn đã nắm khá vững Unit này; có thể chuyển sang Unit tiếp theo.';$('#practiceScore').innerHTML=`<div class="answer">Kết quả: ${score}/${questions.length}. ${advice}<br>Đây là bài luyện tập AI bổ sung.</div>`;window.meai.savePracticeResult({unitId:u.id,score,total:questions.length}).catch(e=>toast(e.message))}
function renderConversationFeedback(feedback){if(!feedback)return '';return `<div class="answer"><b>Điểm tổng hợp: ${esc(feedback.overallScore)}/10</b>${feedback.summary?`<p>${esc(feedback.summary)}</p>`:''}<div class="chat-score-grid">${(feedback.criteria||[]).map(c=>`<article class="chat-score-item"><div class="row" style="justify-content:space-between"><b>${esc(c.label)}</b><span class="tag">${esc(c.score)}/10</span></div><p>${esc(c.comment)}</p><div class="small"><b>Gợi ý sửa:</b> ${esc(c.suggestion)}</div></article>`).join('')}</div></div>`}
function renderTab(b,u){const a=u.analysis;if(!a&&tab!=='ask')return `<div class="empty-inline"><p>Unit này chưa có kết quả phân tích.</p><button class="btn" id="analyzeNow">Phân tích Unit bằng Gemini 3.8 Flash</button></div>`;
if(tab==='overview'){const total=a?.vocabulary?.length||0,verified=(a?.vocabulary||[]).filter(v=>v.sourceVerified).length,pct=total?Math.round(verified/total*100):0;return a?`<h3 class="section-title">Tóm tắt Unit</h3><div class="summary">${esc(a.summary)}</div><div class="stat-row"><span class="stat">CEFR: ${esc(a.cefr||'Chưa xác định')}</span><span class="stat">${a.vocabulary.length} từ vựng</span><span class="stat">Đã đối chiếu nguồn: ${verified}/${total} từ (${pct}%)</span><span class="stat">${a.readings.length} bài đọc</span><span class="stat">${a.exercises.length} bài tập</span><span class="stat">${a.grammar.length} mục lý thuyết</span></div>${a.filteredOut.length?`<hr class="divider"><h3 class="section-title">Nội dung đã loại khỏi học liệu</h3><p class="small">${esc(a.filteredOut.join(' · '))}</p>`:''}`:`<div class="empty-inline">Chưa có phân tích.</div>`}
if(tab==='vocabulary')return `<h3 class="section-title">Từ vựng và thuật ngữ trong Unit</h3>${list(a.vocabulary,(v,i)=>`<div class="term">${esc(v.term)}</div><div class="meaning">${esc(v.meaning)}</div><div class="small">${esc(v.partOfSpeech)}${v.ipa?` · /${esc(v.ipa)}/`:''}${v.page?` · Trang ${v.page}`:''}</div><div class="source-check ${v.sourceVerified?'source-good':'source-bad'}">${v.sourceVerified?'✓ Đã đối chiếu nguồn':'⚠ Dẫn chứng chưa khớp nguồn'}</div><button class="btn secondary" data-speak="${esc(v.term)}">🔊 Phát âm</button>${v.example?`<div class="evidence">Ví dụ trong nguồn: ${esc(v.example)}</div>`:''}<div class="evidence">Dẫn chứng: ${esc(v.evidence||'Chưa có dẫn chứng')}</div><button class="btn secondary" data-ask-term="${esc(v.term)}">Hỏi AI về từ này</button> <button class="btn secondary" data-report="vocabulary" data-report-index="${i}">Báo lỗi nội dung</button>${vocabEditorMarkup(v,i)}`)}`;
if(tab==='readings')return `<h3 class="section-title">Bài đọc</h3>${list(a.readings,(v,i)=>`<div class="term">${esc(v.title)}</div><div class="meaning">${esc(v.summary)}</div><div class="evidence">${esc(v.content)}</div><button class="btn secondary" data-report="reading" data-report-index="${i}">Báo lỗi nội dung</button>`)}`;
if(tab==='exercises')return `<h3 class="section-title">Bài tập gốc trong giáo trình</h3>${list(a.exercises,(v,i)=>`<div class="term">${esc(v.type)}</div><div class="meaning">${esc(v.question)}</div>${v.options.length?`<div class="meaning">${v.options.map(esc).join('<br>')}</div>`:''}${v.answer?`<div class="evidence">Đáp án có trong nguồn: ${esc(v.answer)} ${v.answerEvidence?`<br>${esc(v.answerEvidence)}`:''}</div>`:'<div class="small">Nguồn chưa xác định được đáp án; MEAI không tự gán đáp án chính thức.</div>'}<div class="evidence">Dẫn chứng: ${esc(v.question)}</div><button class="btn secondary" data-report="exercise" data-report-index="${i}">Báo lỗi nội dung</button>`)}`;
if(tab==='grammar')return `<h3 class="section-title">Ngữ pháp và lý thuyết</h3>${list(a.grammar,(v,i)=>`<div class="term">${esc(v.title)}</div><div class="meaning">${esc(v.explanation)}</div><div class="evidence">${esc(v.evidence)}</div><button class="btn secondary" data-report="grammar" data-report-index="${i}">Báo lỗi nội dung</button>`)}`;
if(tab==='practice')return u.practice?`<h3 class="section-title">Bài luyện tập do AI tạo bổ sung</h3><div class="notice">Do AI tạo — nên đối chiếu giáo trình. Đây là câu hỏi bổ sung, không phải bài tập gốc.</div><div class="data-list" id="practiceList">${u.practice.questions.map(renderPracticeItem).join('')}</div><div class="foot-actions"><button class="btn" id="submitPractice">Chấm bài</button><button class="btn secondary" id="newPractice">Tạo bộ câu hỏi mới</button></div><div id="practiceScore"></div>`:`<div class="notice">Do AI tạo — nên đối chiếu giáo trình.</div><div class="empty-inline"><p>Chưa có câu hỏi luyện tập cho Unit này.</p><p class="small">MEAI sẽ tạo câu hỏi bổ sung từ nội dung đã phân tích và phân biệt rõ với bài tập gốc.</p><button class="btn" id="makePractice">Tạo bài luyện tập</button></div>`;
if(tab==='extensions')return `<h3 class="section-title">Học liệu mở rộng bằng Cerebras</h3><div class="notice">Do AI tạo — nên đối chiếu giáo trình.</div><p class="sub">Tạo thêm từ liên quan, bài tập và bài đọc dựa trên Unit đã được Gemini phân tích. Nội dung mới được lưu dùng chung trong Supabase.</p><button class="btn" id="generateExtensions">${u.extensions?'Tạo lại học liệu mở rộng':'Tạo học liệu mở rộng'}</button>${u.extensions?`<div class="stat-row"><span class="stat">${u.extensions.vocabulary?.length||0} từ mở rộng</span><span class="stat">${u.extensions.exercises?.length||0} bài tập mới</span><span class="stat">${u.extensions.readings?.length||0} bài đọc mới</span></div><h4>Từ vựng liên quan</h4>${list(u.extensions.vocabulary||[],(v,i)=>`<b>${esc(v.term)}</b><div>${esc(v.meaning)}</div><div class="small">${esc(v.partOfSpeech||'')}</div><div class="evidence">${esc(v.example||'')}</div><button class="btn secondary" data-report="extension_vocabulary" data-report-index="${i}">Báo lỗi nội dung</button>`)}<h4>Bài tập mới</h4>${list(u.extensions.exercises||[],(v,i)=>`<b>${esc(v.question)}</b><div>${(v.options||[]).map(esc).join('<br>')}</div><div class="evidence">${esc(v.answer||'')} · ${esc(v.explanation||'')}</div><button class="btn secondary" data-report="extension_exercise" data-report-index="${i}">Báo lỗi nội dung</button>`)}<h4>Bài đọc mới</h4>${list(u.extensions.readings||[],(v,i)=>`<b>${esc(v.title)}</b><div class="summary">${esc(v.content)}</div>${(v.questions||[]).map(q=>`<div>${esc(q.question)} · ${esc(q.answer||'')}</div>`).join('')}<button class="btn secondary" data-report="extension_reading" data-report-index="${i}">Báo lỗi nội dung</button>`)}`:''}`;
if(tab==='writing')return `<h3 class="section-title">Luyện viết tiếng Anh</h3><p class="sub">Groq chấm điểm, sửa lỗi và so sánh với tối đa 3 bài viết gần nhất của bạn.</p><textarea class="textarea" id="writingInput" style="min-height:160px" placeholder="Write your answer in English..."></textarea><div class="foot-actions"><button class="btn" id="checkWriting">Nhận góp ý</button></div><div id="writingAnswer"></div>`;
if(tab==='conversation'){const session=[...(state.sessions||[])].reverse().find(s=>s.bookId===b.id&&s.unitId===u.id),selectedScenario=session?.scenarioId||'unit_free',scenarioOptions=[['unit_free','Hội thoại tự do theo nội dung Unit'],['radio','Đàm thoại vô tuyến'],['sitrep','Báo cáo tình huống (SITREP)'],['mission_brief','Brief nhiệm vụ']];return `<h3 class="section-title">Luyện hội thoại tiếng Anh</h3><p class="sub">AI dùng Groq, nói tiếng Anh đơn giản và bám từ vựng của Unit đang chọn. Các kịch bản chuyên ngành đều là tình huống giả định để luyện ngôn ngữ.</p><label class="label" for="chatScenario">Kịch bản</label><select class="select" id="chatScenario">${scenarioOptions.map(([id,label])=>`<option value="${id}" ${selectedScenario===id?'selected':''}>${label}</option>`).join('')}</select><p class="small">Kịch bản được chốt khi bắt đầu phiên. Đổi lựa chọn rồi bấm “Bắt đầu hội thoại mới” để chuyển kịch bản.</p>${session?`<div class="tag chat-scenario-label">Phiên hiện tại: ${esc(session.scenarioLabel||session.scenario||'Hội thoại tự do theo nội dung Unit')}</div><div class="data-list" style="margin-top:16px">${session.history.map(m=>`<div class="data-item"><div class="small">${m.role==='user'?'BẠN':'ĐỐI TÁC AI'}</div><div class="summary" style="margin-top:6px">${esc(m.text)}</div></div>`).join('')}</div>`:''}<div class="foot-actions"><button class="btn" id="chatStart">${session?'Bắt đầu hội thoại mới':'Bắt đầu hội thoại'}</button>${session&&!session.endedAt?'<button class="btn secondary" id="endChat">Kết thúc và nhận xét</button>':''}</div>${session&&!session.endedAt?`<label class="label" for="chatInput">Câu trả lời của bạn bằng tiếng Anh</label><textarea class="textarea" id="chatInput" placeholder="Type your reply in English..."></textarea><div class="foot-actions"><button class="btn" id="chatSend">Gửi câu trả lời</button></div>`:session?.endedAt?'<div class="notice" style="margin-top:14px">Phiên đã kết thúc. Bạn có thể bắt đầu phiên mới với cùng kịch bản hoặc chọn kịch bản khác.</div>':''}${session?.feedback?renderConversationFeedback(session.feedback):''}`}
if(tab==='ask')return `<h3 class="section-title">Hỏi AI về từ vựng và nội dung đang học</h3><p class="sub">Hỏi nghĩa, loại từ, cách dùng, sự khác nhau giữa hai từ, cụm từ, hoặc ví dụ trong ngữ cảnh. AI ưu tiên giáo trình đang chọn và sẽ nói rõ khi nguồn chưa đủ căn cứ.</p><label class="label">Từ hoặc cụm từ (không bắt buộc)</label><input class="input" id="termInput" placeholder="Ví dụ: transmission, aircraft operator"><label class="label">Câu hỏi</label><textarea class="textarea" id="questionInput" placeholder="Ví dụ: Từ này có nghĩa gì trong Unit này? Khác gì với communicate?"></textarea><div class="foot-actions"><button class="btn" id="askSend">Gửi câu hỏi</button></div><div id="answer"></div>`;
return ''}
function list(items,fn){return items.length?`<div class="data-list">${items.map((v,i)=>`<div class="data-item">${fn(v,i)}</div>`).join('')}</div>`:'<div class="empty-inline">Không tìm thấy mục nào trong nhóm này. Nếu tài liệu có nội dung tương ứng, hãy kiểm tra lại phần trích xuất hoặc phân tích lại Unit.</div>'}
function auditListMarkup(logs=[],error=''){const labels={user_created:'Tạo tài khoản',users_excel_imported:'Nhập Excel',user_role_changed:'Đổi quyền',ai_keys_changed:'Thay API key',unit_approval_changed:'Duyệt nội dung'};const rows=(logs||[]).map(x=>'<tr><td>'+esc(labels[x.action]||x.action)+'</td><td>'+esc(x.actor_id||'Không rõ')+'</td><td>'+esc(x.target_type||'')+' '+esc(x.target_id||'')+'</td><td>'+esc(JSON.stringify(x.details||{}))+'</td><td>'+esc((x.created_at||'').replace('T',' ').slice(0,16))+'</td></tr>').join('');return '<div class="card" style="margin-top:16px"><h3 class="section-title">Nhật ký thao tác Admin</h3>'+(error?'<p class="small">Chưa đọc được audit log: '+esc(error)+'</p>':'')+'<div class="table-wrap"><table><thead><tr><th>Thao tác</th><th>Admin ID</th><th>Đối tượng</th><th>Chi tiết</th><th>Thời gian</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>'}
function reportListMarkup(reports,reportsError=''){const kinds={vocabulary:'Từ vựng',exercise:'Bài tập',reading:'Bài đọc',grammar:'Lý thuyết',ai_practice:'Luyện tập AI',extension_vocabulary:'Từ vựng mở rộng',extension_exercise:'Bài tập mở rộng',extension_reading:'Bài đọc mở rộng'};return `<div class="card" style="margin-top:16px"><h3 class="section-title">Báo lỗi nội dung (${reports.length})</h3>${reportsError?`<div class="notice">${esc(reportsError)}</div>`:''}${reports.length?`<div class="data-list">${reports.map(r=>`<article class="data-item"><div class="row" style="justify-content:space-between"><b>${esc(kinds[r.content_type]||r.content_type)} · ${esc(r.unit?.unit_name||'Unit đã xóa')}</b><span class="tag ${r.status==='resolved'?'review-approved':'review-pending'}">${r.status==='resolved'?'Đã xử lý':'Chờ xử lý'}</span></div><div class="small">${esc(r.reporter?.full_name||r.reporter?.username||'Người dùng')} · ${esc((r.created_at||'').replace('T',' ').slice(0,16))}</div><pre class="report-content">${esc(JSON.stringify(r.reported_content,null,2)||'')}</pre>${r.note?`<div class="meaning"><b>Ghi chú:</b> ${esc(r.note)}</div>`:''}<button class="btn secondary" data-resolve-report="${esc(r.id)}" data-resolved="${r.status==='resolved'?'false':'true'}">${r.status==='resolved'?'Mở lại báo lỗi':'Đánh dấu đã xử lý'}</button></article>`).join('')}</div>`:'<div class="empty-inline">Chưa có báo lỗi nội dung.</div>'}</div>`}
async function ask(){const question=$('#questionInput')?.value.trim()||'',term=$('#termInput')?.value.trim()||'';if(!question&&!term){toast('Nhập từ vựng hoặc câu hỏi trước.');return}await call(async()=>{const answer=await window.meai.ask({bookId:selectedBook.id,unitId:selectedUnit,question,term});$('#answer').innerHTML=`<div class="answer">${esc(answer)}</div>`})}
function renderReview(){reviewWords=[];for(const b of state.books)for(const u of b.units)for(const w of (u.analysis?.vocabulary||[]))reviewWords.push({book:b,unit:u,word:w,key:`${b.id}:${u.id}:${w.term}`});if(reviewMode==='flash'){renderFlashcard();return}const dueCount=reviewWords.filter(x=>{const r=state.reviewStatus?.[x.key];return !r||typeof r!=='object'||!r.dueAt||Date.parse(r.dueAt)<=Date.now()}).length;$('#app').innerHTML=header('Ôn từ vựng','Lịch ôn tự điều chỉnh theo câu trả lời của bạn.','<button class="btn" id="startFlash">Ôn thẻ đến hạn</button>')+`<div class="card"><input class="input" id="reviewSearch" placeholder="Tìm từ tiếng Anh, nghĩa tiếng Việt hoặc giáo trình..."><div class="small" style="margin:10px 0 16px">${reviewWords.length} thẻ · ${dueCount} thẻ đến hạn</div><div id="reviewList" class="data-list">${reviewRows(reviewWords)}</div></div>`;$('#startFlash').onclick=()=>{reviewDueOnly=true;reviewMode='flash';flashIndex=0;flashRevealed=false;renderReview()};$('#reviewSearch').addEventListener('input',()=>{const q=$('#reviewSearch').value.toLowerCase();$('#reviewList').innerHTML=reviewRows(reviewWords.filter(x=>`${x.word.term} ${x.word.meaning} ${x.book.title} ${x.unit.title}`.toLowerCase().includes(q)));wireReviewButtons()});wireReviewButtons()}
function renderFlashcard(){const now=Date.now(),activeReviewWords=reviewDueOnly?reviewWords.filter(x=>{const r=state.reviewStatus?.[x.key];return !r||typeof r!=='object'||!r.dueAt||Date.parse(r.dueAt)<=now}):reviewWords;if(!activeReviewWords.length){const allDone=reviewWords.length>0;$('#app').innerHTML=header(allDone?'Đã ôn xong thẻ đến hạn':'Ôn từ vựng',allDone?'Các thẻ tiếp theo sẽ đến hạn theo lịch ôn.':'Chưa có từ vựng để ôn.',allDone?'<button class="btn" id="startAllCards">Ôn lại tất cả</button>':'<button class="btn secondary" id="backToList">Về danh sách</button>')+'<div class="card empty-inline">'+(allDone?'Bạn đã hoàn thành các thẻ đến hạn hôm nay.':'Nhập và phân tích giáo trình trước khi ôn từ vựng.')+'</div>';if(allDone)$('#startAllCards').onclick=()=>{reviewDueOnly=false;renderFlashcard()};else $('#backToList').onclick=()=>{reviewMode='list';renderReview()};return}flashIndex=((flashIndex%activeReviewWords.length)+activeReviewWords.length)%activeReviewWords.length;const x=activeReviewWords[flashIndex],status=state.reviewStatus?.[x.key];$('#app').innerHTML=header('Ôn từ vựng bằng thẻ',`Thẻ ${flashIndex+1}/${activeReviewWords.length}. Hãy tự nhớ nghĩa trước khi lật thẻ.`, '<button class="btn secondary" id="backToList">Về danh sách</button>')+`<div class="card" style="max-width:760px;margin:auto;text-align:center;padding:34px 28px"><div class="tag">${esc(x.book.title)} · ${esc(x.unit.title)}</div><div style="font-size:30px;font-weight:800;margin:32px 0 18px;color:#25365b">${esc(x.word.term)}</div><button class="btn secondary" id="speakFlash">🔊 Phát âm</button>${flashRevealed?`<div class="summary" style="font-size:17px">${esc(x.word.meaning)}</div><div class="small" style="margin-top:14px">${esc(x.word.partOfSpeech)}</div><div class="evidence" style="text-align:left">${esc(x.word.evidence)}</div>`:'<p class="sub">Bạn nhớ nghĩa của từ này không? Hãy thử trả lời trước khi lật thẻ.</p>'}<div class="foot-actions" style="justify-content:center;margin-top:26px"><button class="btn" id="flipCard">${flashRevealed?'Ẩn nghĩa':'Lật thẻ xem nghĩa'}</button><button class="btn secondary" id="nextCard">Thẻ tiếp theo →</button></div>${flashRevealed?`<div class="foot-actions" style="justify-content:center"><button class="btn" id="markKnown">Đã nhớ</button><button class="btn secondary" id="markReview">Cần ôn lại</button></div>`:''}<div class="small" style="margin-top:12px">${(status===true||status?.known===true)?`Đã nhớ · ôn lại sau ${status?.intervalDays||1} ngày`:status===false||status?.known===false?'Cần ôn lại sớm':'Chưa đánh dấu'}</div></div>`;$('#backToList').onclick=()=>{reviewMode='list';renderReview()};$('#flipCard').onclick=()=>{flashRevealed=!flashRevealed;renderFlashcard()};$('#speakFlash').onclick=()=>speakEnglish(x.word.term);$('#nextCard').onclick=()=>{flashIndex=(flashIndex+1)%activeReviewWords.length;flashRevealed=false;renderFlashcard()};$('#markKnown')?.addEventListener('click',()=>call(async()=>{await window.meai.markReview({key:x.key,known:true});await refresh();flashIndex=(flashIndex+1)%Math.max(1,activeReviewWords.length);flashRevealed=false;renderReview()}));$('#markReview')?.addEventListener('click',()=>call(async()=>{await window.meai.markReview({key:x.key,known:false});await refresh();flashIndex=(flashIndex+1)%Math.max(1,activeReviewWords.length);flashRevealed=false;renderReview()}))}
function wireReviewButtons(){document.querySelectorAll('[data-review-book]').forEach(x=>x.onclick=()=>{selectedBook=state.books.find(b=>b.id===x.dataset.reviewBook);selectedUnit=x.dataset.reviewUnit;view='book';tab='ask';renderBook();$('#termInput').value=x.dataset.reviewTerm;$('#questionInput').focus()})}
function reviewRows(words){return words.length?words.slice(0,500).map(x=>`<div class="data-item"><div class="term">${esc(x.word.term)}</div><div class="meaning">${esc(x.word.meaning)}</div><div class="small">${esc(x.book.title)} · ${esc(x.unit.title)} ${(state.reviewStatus?.[x.key]===true||state.reviewStatus?.[x.key]?.known===true)?'· Đã nhớ':(state.reviewStatus?.[x.key]===false||state.reviewStatus?.[x.key]?.known===false)?'· Cần ôn lại':'· Chưa ôn'}</div><div class="foot-actions"><button class="btn secondary" data-review-book="${x.book.id}" data-review-unit="${x.unit.id}" data-review-term="${esc(x.word.term)}">Hỏi AI về từ này</button></div></div>`).join(''):'<div class="empty-inline">Chưa có từ vựng. Hãy nhập và phân tích một giáo trình trước.</div>'}
function renderSettings(){const model=state.settings.model||'gemini-3.8-flash',counts=state.keyCounts||{};$('#app').innerHTML=header('Cài đặt AI','Cấu hình nhiều API key cho từng nhà cung cấp. Các key được lưu mã hóa trong hồ sơ Windows.')+`<div class="card settings"><h3 class="section-title">Gemini — phân tích, tách Unit và hỏi đáp</h3><label class="label">Gemini API keys (phân tách bằng dấu phẩy)</label><input class="input" id="geminiKeys" type="password" autocomplete="off" placeholder="${counts.gemini?`Đã lưu ${counts.gemini} key; nhập danh sách mới để thay thế`:'Nhập một hoặc nhiều Gemini API key'}"><label class="label">Model Gemini</label><select class="select" id="model"><option value="gemini-3.8-flash" ${model==='gemini-3.8-flash'?'selected':''}>Gemini 3.8 Flash (Stable)</option><option value="gemini-3-flash-preview" ${model==='gemini-3-flash-preview'?'selected':''}>Gemini 3 Flash Preview</option></select><h3 class="section-title" style="margin-top:22px">Groq — hội thoại và chấm bài viết</h3><label class="label">Groq API keys (phân tách bằng dấu phẩy)</label><input class="input" id="groqKeys" type="password" autocomplete="off" placeholder="${counts.groq?`Đã lưu ${counts.groq} key; nhập danh sách mới để thay thế`:'Nhập một hoặc nhiều Groq API key'}"><h3 class="section-title" style="margin-top:22px">Cerebras — bài tập và học liệu mở rộng</h3><label class="label">Cerebras API keys (phân tách bằng dấu phẩy)</label><input class="input" id="cerebrasKeys" type="password" autocomplete="off" placeholder="${counts.cerebras?`Đã lưu ${counts.cerebras} key; nhập danh sách mới để thay thế`:'Nhập một hoặc nhiều Cerebras API key'}"><p class="small">Để giữ key đã lưu, để trống ô. Để xóa một nhóm key, nhập CLEAR. Các key được luân phiên; khi gặp rate limit/quota, hệ thống thử key kế tiếp.</p><div class="foot-actions"><button class="btn" id="saveSettings">Lưu cài đặt</button><button class="btn secondary" data-test-provider="gemini">Thử Gemini</button><button class="btn secondary" data-test-provider="groq">Thử Groq</button><button class="btn secondary" data-test-provider="cerebras">Thử Cerebras</button></div><div id="testResult"></div><hr class="divider"><h3 class="section-title">Nguyên tắc phân tích</h3><p class="summary">Gemini phân tích tài liệu và hỏi đáp; Groq hỗ trợ hội thoại, chấm viết và so sánh 3 bài gần nhất; Cerebras sinh bài tập, từ vựng và bài đọc mở rộng, lưu vào Supabase. Tài liệu được gửi tới nhà cung cấp AI tương ứng để xử lý.</p></div>`;
$('#saveSettings').onclick=()=>call(async()=>{const parse=id=>{const v=$('#'+id).value.trim();return !v?undefined:v.toUpperCase()==='CLEAR'?'__CLEAR__':v.split(',').map(x=>x.trim()).filter(Boolean)};const providerKeys={gemini:parse('geminiKeys'),groq:parse('groqKeys'),cerebras:parse('cerebrasKeys')};await window.meai.saveSettings({providerKeys,model:$('#model').value});await refresh();renderSettings();toast('Đã lưu cấu hình AI.')});
document.querySelectorAll('[data-test-provider]').forEach(btn=>btn.onclick=()=>call(async()=>{const provider=btn.dataset.testProvider,r=await window.meai.testAI(provider);$('#testResult').innerHTML=`<div class="answer">${esc(provider)} kết nối thành công: ${esc(r.response)}</div>`}));}
$('#cancelContentReport').onclick=()=>{pendingReport=null;$('#reportDialog').close()};$('#submitContentReport').onclick=()=>call(async()=>{if(!pendingReport)throw Error('Không còn nội dung cần báo.');await window.meai.reportContent({...pendingReport,note:$('#reportNote').value});pendingReport=null;$('#reportDialog').close();toast('Đã gửi báo lỗi nội dung cho Admin.')});document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('#logoutBtn').onclick=async()=>{try{await window.meai.logout();busy=false;view='library';selectedBook=null;selectedUnit=null;await refresh();renderLogin();toast('Đã đăng xuất.')}catch(e){toast(e.message||String(e))}};$('#saveTextImport').onclick=importText;$('#cancelTextImport').onclick=()=>$('#textImportDialog').close();
let selectedTextForAsk='';document.addEventListener('mouseup',e=>{const text=window.getSelection()?.toString().trim()||'',button=$('#askSelection');if(view!=='book'||!state?.authenticated||text.length<2||text.length>300||!e.target.closest('#app')){button.hidden=true;return}selectedTextForAsk=text;button.style.left=Math.min(e.clientX,window.innerWidth-190)+'px';button.style.top=Math.min(e.clientY+8,window.innerHeight-50)+'px';button.hidden=false});$('#askSelection').onclick=()=>{if(!selectedTextForAsk||!selectedBook)return;view='book';tab='ask';renderBook();$('#termInput').value=selectedTextForAsk;$('#questionInput').value='Giải thích nghĩa và cách dùng đoạn đã chọn trong ngữ cảnh Unit này.';$('#questionInput').focus();$('#askSelection').hidden=true};
window.meai.onProgress(p=>{if(p.message)toast(p.message)});window.meai.onUnitUpdated(async()=>{await refresh();if(view==='book')renderBook()});window.meai.onAuditWarning(message=>toast(message));
refresh().then(render).catch(e=>toast(e.message));
